const first = $input.first().json || {};

// استخراج الكائن الرئيسي سواء جاء من payload أو data أو مباشرة
const rawData = first.payload?.data || first.payload || first.data || first;

const errors = [];
const warnings = [];

const nk = (s) => String(s == null ? '' : s).toLowerCase().replace(/[^a-z0-9]+/g, '');
const stripCtl = (s) => String(s == null ? '' : s).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '');
const oneLine = (s, max) => stripCtl(s).replace(/\s+/g, ' ').trim().slice(0, max);
const multiLine = (s, max) => stripCtl(s).replace(/\r\n?/g, '\n').replace(/\n{3,}/g, '\n\n').trim().slice(0, max);

const resolveValue = (v) => {
  if (Array.isArray(v)) {
    return v.map((x) => (x && typeof x === 'object' ? x.name || x.text || x.url || '' : String(x))).join(', ');
  } else if (v && typeof v === 'object') {
    return v.name || v.text || v.url || '';
  }
  return v == null ? '' : String(v);
};

// 1. تجميع البيانات سواء كانت في fields Array أو كائنات أسئلة question_*
const byLabel = {};

// فحص لو البيانات قادمة كـ Array
const fieldsList = Array.isArray(rawData.fields) ? rawData.fields : [];
for (const f of fieldsList) {
  if (!f || typeof f !== 'object') continue;
  const key = nk(f.label || f.title || f.key);
  if (key && byLabel[key] === undefined) byLabel[key] = resolveValue(f.value);
}

// فحص لو البيانات قادمة كأزواج مفاتيح مثل question_74K64P (كما بالصورة)
for (const k of Object.keys(rawData)) {
  const item = rawData[k];
  if (item && typeof item === 'object' && (item.label || item.title)) {
    const key = nk(item.label || item.title);
    if (key && byLabel[key] === undefined) {
      byLabel[key] = resolveValue(item.value);
    }
  } else if (typeof item === 'string' || typeof item === 'number') {
    const key = nk(k);
    if (key && byLabel[key] === undefined) byLabel[key] = String(item);
  }
}

const pick = (...labels) => {
  for (const l of labels) {
    const v = byLabel[nk(l)];
    if (v !== undefined && String(v).trim() !== '') return String(v);
  }
  return '';
};

const pickStarts = (prefix) => {
  const p = nk(prefix);
  const k = Object.keys(byLabel).find((k) => k.startsWith(p) && String(byLabel[k]).trim() !== '');
  return k ? byLabel[k] : '';
};

const SIZES = ['1–10 employees', '11–50 employees', '51–200 employees', '201–500 employees', '500+ employees'];
const BUDGETS = ['Under $1,000', '$1,000–$5,000', '$5,000–$10,000', '$10,000–$25,000', '$25,000+'];
const TIMELINES = ['Immediately', 'Within 1 month', 'Within 3 months', 'More than 3 months', 'Just exploring'];

const nrm = (s) => String(s).toLowerCase().replace(/[\u2010-\u2015\u2212]/g, '-').replace(/\s+/g, ' ').trim();
const canon = (raw, list, label) => {
  if (!raw) return '';
  const hit = list.find((o) => nrm(o) === nrm(raw));
  if (!hit) warnings.push(label + ' value not recognized and ignored: ' + String(raw).slice(0, 60));
  return hit || '';
};

const fullName = oneLine(pick('Full Name', 'Name'), 120);
const workEmail = oneLine(pick('Work Email', 'Email'), 200).toLowerCase();
const companyName = oneLine(pick('Company Name', 'Company'), 160);
const jobTitle = oneLine(pick('Job Title', 'Title'), 120);
let phone = oneLine(pick('Phone Number', 'Phone'), 40).replace(/[^0-9+()\-\s.]/g, '').trim();
if (phone && phone.replace(/\D/g, '').length < 6) { warnings.push('Phone number ignored (too short)'); phone = ''; }
const industry = oneLine(pick('Industry'), 120);
let website = oneLine(pick('Company Website', 'Website'), 300);
if (website) {
  if (!/^https?:\/\//i.test(website)) website = 'https://' + website;
  if (!/^https?:\/\/[^\s\/$.?#][^\s]*\.[^\s]{2,}$/i.test(website)) { warnings.push('Website ignored (invalid URL)'); website = ''; }
}
const companySize = canon(oneLine(pick('Company Size'), 80), SIZES, 'Company Size');
const budget = canon(oneLine(pick('Estimated Budget', 'Budget'), 80), BUDGETS, 'Estimated Budget');
const timeline = canon(oneLine(pick('Expected Timeline', 'Timeline'), 80), TIMELINES, 'Expected Timeline');
const problem = multiLine(pick('What problem are you trying to solve?') || pickStarts('what problem') || pick('Project Requirements', 'Problem'), 4000);
const additionalInfo = multiLine(pick('Additional Information', 'Additional Info'), 2000);

if (!fullName) errors.push('Full Name is required');
if (!workEmail) errors.push('Work Email is required');
else if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(workEmail)) errors.push('Work Email is not a valid email address');
if (!companyName) errors.push('Company Name is required');

let leadId = String(rawData.submissionId || rawData.responseId || first.submissionId || '').replace(/[^A-Za-z0-9_-]/g, '').slice(0, 64);
if (!leadId) {
  const src = [workEmail, companyName, rawData.createdAt || first.createdAt || '', problem].join('|');
  let h = 5381;
  for (let i = 0; i < src.length; i++) { h = ((h << 5) + h + src.charCodeAt(i)) >>> 0; }
  leadId = 'gen-' + h.toString(16);
  warnings.push('No Tally submission ID found; generated a stable fallback ID');
}

const created = new Date(rawData.createdAt || first.createdAt || '');
const submittedAt = isNaN(created.getTime()) ? new Date().toISOString() : created.toISOString();

const injectionRe = /(ignore\s+(all\s+|any\s+|the\s+)?(previous|prior|above|earlier)\s+(instructions?|prompts?|rules)|disregard\s+(all\s+|the\s+)?(previous|prior|above|system)|you\s+are\s+now\s+(a|an|the)\b|reveal\s+(your|the)\s+(system\s+)?(prompt|instructions)|(score|rate|classify)\s+(this|me|us|the)?\s*(lead\s+)?(as\s+)?(100|hot)\b)/i;
const injectionSuspected = injectionRe.test([problem, additionalInfo, fullName, companyName, jobTitle, industry].join(' \n '));
if (injectionSuspected) warnings.push('Possible prompt-injection text detected in submission; treated as data only');

return [{
  json: {
    valid: errors.length === 0,
    errors,
    warnings,
    leadId,
    formId: oneLine(rawData.formId || first.formId || '', 40),
    formName: oneLine(rawData.formName || first.formName || '', 120),
    submittedAt,
    injectionSuspected,
    lead: { fullName, workEmail, companyName, jobTitle, phone, companySize, industry, website, budget, problem, timeline, additionalInfo }
  }
}];

const norm = $('Normalize & Validate Submission').first().json;
const L = norm.lead;
const res = $('AI Lead Qualification (Basic LLM Chain)').first().json || {};

const BUDGET = { 'Under $1,000': 5, '$1,000–$5,000': 12, '$5,000–$10,000': 18, '$10,000–$25,000': 24, '$25,000+': 30 };
const SIZE = { '1–10 employees': 5, '11–50 employees': 9, '51–200 employees': 14, '201–500 employees': 17, '500+ employees': 20 };
const TIME = { 'Immediately': 20, 'Within 1 month': 16, 'Within 3 months': 11, 'More than 3 months': 5, 'Just exploring': 2 };
const UNKNOWN = { budget: 12, size: 9, fit: 10, timeline: 8 };
const ACTION = { Hot: 'Contact within 24 hours.', Warm: 'Follow up within 2-3 business days.', Cold: 'Add to a low-priority nurture sequence.' };

const num = (v) => { const n = Number(v); return Number.isFinite(n) ? Math.round(n) : NaN; };
const txt = (v, max) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim().slice(0, max);

const notes = [];
(norm.warnings || []).forEach((w) => notes.push('Warning: ' + w));
notes.push('Source: Tally form ' + (norm.formName || 'unknown') + (norm.formId ? ' (' + norm.formId + ')' : ''));

let ai = null;
let aiError = '';
try {
  if (res.error) {
    const m = typeof res.error === 'string' ? res.error : (res.error.message || res.error.description || JSON.stringify(res.error));
    throw new Error('LLM chain failed: ' + String(m).slice(0, 250));
  }
  let parsed;
  if (res.project_fit_score !== undefined || res.talking_points !== undefined) {
    // Basic LLM Chain already returned the parsed JSON object (json_object response format)
    parsed = res;
  } else {
    const content = typeof res.text === 'string' ? res.text : (typeof res.output === 'string' ? res.output : (typeof res.response === 'string' ? res.response : ''));
    if (!content) throw new Error('LLM chain returned an empty response');
    const raw = content.trim().replace(/^\x60{3}(?:json)?\s*/i, '').replace(/\s*\x60{3}$/, '');
    const s = raw.indexOf('{');
    const e = raw.lastIndexOf('}');
    if (s < 0 || e <= s) throw new Error('AI response did not contain a JSON object');
    try { parsed = JSON.parse(raw.slice(s, e + 1)); } catch (x) { throw new Error('AI response was not valid JSON'); }
  }
  const fit = num(parsed.project_fit_score);
  if (!Number.isFinite(fit)) throw new Error('AI response is missing project_fit_score');
  const points = Array.isArray(parsed.talking_points) ? parsed.talking_points.map((t) => txt(t, 300)).filter(Boolean) : [];
  if (points.length < 3) throw new Error('AI response did not include 3 talking points');
  const summary = txt(parsed.summary, 600);
  const reason = txt(parsed.qualification_reason, 900);
  const action = txt(parsed.recommended_action, 300);
  if (!summary || !reason || !action) throw new Error('AI response is missing summary, reasoning or recommended action');
  ai = { parsed, fit, points: points.slice(0, 3), summary, reason, action };
} catch (err) {
  aiError = String(err && err.message ? err.message : err);
}

const out = {};
const put = (k, v) => { if (v !== undefined && v !== null && String(v).trim() !== '') out[k] = v; };

put('Lead ID', norm.leadId);
put('Full Name', L.fullName);
put('Work Email', L.workEmail);
put('Company Name', L.companyName);
put('Job Title', L.jobTitle);
put('Phone Number', L.phone);
put('Company Size', L.companySize);
put('Industry', L.industry);
put('Website', L.website);
put('Estimated Budget', L.budget);
put('Project Requirements', L.problem);
put('Expected Timeline', L.timeline);
put('Additional Information', L.additionalInfo);
put('Submission Date', norm.submittedAt);

if (ai) {
  const budgetScore = L.budget ? BUDGET[L.budget] : UNKNOWN.budget;
  const sizeScore = L.companySize ? SIZE[L.companySize] : UNKNOWN.size;
  const timelineScore = L.timeline ? TIME[L.timeline] : UNKNOWN.timeline;
  const fitScore = L.problem ? Math.max(0, Math.min(30, ai.fit)) : UNKNOWN.fit;
  const total = budgetScore + sizeScore + fitScore + timelineScore;
  const cls = total >= 70 ? 'Hot' : (total >= 40 ? 'Warm' : 'Cold');

  const p = ai.parsed;
  const adj = [];
  if (num(p.project_fit_score) !== fitScore) adj.push('project fit ' + p.project_fit_score + ' -> ' + fitScore);
  if (num(p.qualification_score) !== total) adj.push('total ' + p.qualification_score + ' -> ' + total);
  const clsChanged = String(p.classification) !== cls;
  if (clsChanged) adj.push('classification ' + p.classification + ' -> ' + cls);
  if (adj.length) notes.push('Score normalized to the rubric (AI value -> final): ' + adj.join('; '));
  notes.push('Score breakdown: budget ' + budgetScore + '/30, company size ' + sizeScore + '/20, project fit ' + fitScore + '/30, timeline ' + timelineScore + '/20 = ' + total + '/100');
  if (clsChanged) notes.push('Recommended action replaced to match the final classification (AI suggested: ' + ai.action + ')');

  out['AI Qualification Score'] = total;
  put('Lead Classification', cls);
  put('AI Summary', ai.summary);
  put('Recommended Talking Points', ai.points.map((t, i) => (i + 1) + '. ' + t).join('\n'));
  put('Qualification Reason', ai.reason);
  put('Recommended Action', clsChanged ? ACTION[cls] : ai.action);
  if (norm.injectionSuspected) {
    put('Processing Status', 'Needs Review');
    notes.push('Flagged for review: submission contains text that looks like an attempt to manipulate the AI.');
  } else {
    put('Processing Status', 'Qualified');
  }
} else {
  notes.push('AI qualification FAILED: ' + aiError);
  put('AI Summary', 'AI qualification unavailable. Manual review required.');
  put('Processing Status', 'Needs Review');
}

put('Processing Notes', notes.join('\n'));
return [{ json: out }];

const rec = $input.first().json || {};
const f = (rec.fields && typeof rec.fields === 'object') ? rec.fields : rec;
const recordId = rec.id || '';
// TODO: set your own Airtable base and table IDs (see the Airtable URL: airtable.com/<baseId>/<tableId>/...)
const AIRTABLE_BASE_ID = 'appXXXXXXXXXXXXXX';
const AIRTABLE_TABLE_ID = 'tblXXXXXXXXXXXXXX';
const recordUrl = recordId ? 'https://airtable.com/' + AIRTABLE_BASE_ID + '/' + AIRTABLE_TABLE_ID + '/' + recordId : '';

const esc = (v) => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const val = (v) => (v !== undefined && v !== null && String(v).trim() !== '' ? esc(v) : '_Not provided_');

const cls = f['Lead Classification'] || '';
const status = f['Processing Status'] || '';
const score = f['AI Qualification Score'];

let header;
if (!cls) header = '⚠️ *NEW LEAD: AI QUALIFICATION UNAVAILABLE* (manual review needed)';
else if (cls === 'Hot') header = '🔥 *NEW HOT LEAD* (High Priority)';
else if (cls === 'Warm') header = '🟠 *NEW WARM LEAD* (Standard Follow-up)';
else header = '🧊 *NEW COLD LEAD* (Low Priority)';

const points = String(f['Recommended Talking Points'] || '').split('\n').map((l) => l.trim()).filter(Boolean).map(esc);

const lines = [];
lines.push(header);
if (status === 'Needs Review' && cls) lines.push('⚠️ _Flagged for review: see Processing Notes in Airtable._');
lines.push('');
lines.push('👤 *Contact:* ' + val(f['Full Name']));
lines.push('🏢 *Company:* ' + val(f['Company Name']));
lines.push('💼 *Job Title:* ' + val(f['Job Title']));
lines.push('📧 *Email:* ' + val(f['Work Email']));
lines.push('📞 *Phone:* ' + val(f['Phone Number']));
lines.push('🌐 *Website:* ' + val(f['Website']));
lines.push('🏭 *Industry:* ' + val(f['Industry']));
lines.push('');
lines.push('📊 *AI QUALIFICATION*');
if (cls) {
  lines.push('*Score:* ' + esc(score) + '/100');
  lines.push('*Classification:* ' + esc(cls.toUpperCase()));
} else {
  lines.push('*Score:* _Unavailable_');
  lines.push('*Classification:* _Unavailable_');
}
lines.push('');
lines.push('💰 *Budget:* ' + val(f['Estimated Budget']));
lines.push('👥 *Company Size:* ' + val(f['Company Size']));
lines.push('⏰ *Timeline:* ' + val(f['Expected Timeline']));
lines.push('');
lines.push('🧠 *AI SUMMARY*');
lines.push(val(f['AI Summary']));
if (f['Qualification Reason']) { lines.push(''); lines.push('📝 *WHY THIS SCORE*'); lines.push(esc(f['Qualification Reason'])); }
if (points.length) { lines.push(''); lines.push('🎯 *SALES TALKING POINTS*'); points.forEach((p) => lines.push(p)); }
if (f['Recommended Action']) { lines.push(''); lines.push('🚀 *RECOMMENDED ACTION*'); lines.push(esc(f['Recommended Action'])); }
lines.push('');
lines.push(recordUrl ? '🔗 *Airtable Record:* <' + recordUrl + '|Open lead record>' : '🔗 *Airtable Record:* _link unavailable_');

return [{ json: { slack_text: lines.join('\n'), recordId, recordUrl, classification: cls, existingNotes: String(f['Processing Notes'] || '') } }];

const f = $('AI Scoring & Validation').first().json;
const err = $input.first().json.error;
const esc = (v) => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const msg = String(typeof err === 'string' ? err : ((err && (err.message || err.description)) || 'Unknown Airtable error')).replace(/\s+/g, ' ').slice(0, 300);
const lines = [
  '🚨 *LEAD NOT SAVED: Airtable record creation failed*',
  'No CRM record exists for this lead. Please follow up manually and re-check Airtable.',
  '',
  '👤 *Contact:* ' + esc(f['Full Name'] || 'n/a'),
  '🏢 *Company:* ' + esc(f['Company Name'] || 'n/a'),
  '📧 *Email:* ' + esc(f['Work Email'] || 'n/a'),
  '🆔 *Lead ID:* ' + esc(f['Lead ID'] || 'n/a'),
  '📊 *AI score:* ' + (f['AI Qualification Score'] !== undefined ? esc(f['AI Qualification Score']) + '/100 (' + esc(f['Lead Classification'] || '') + ')' : 'unavailable'),
  '',
  '❌ *Error:* ' + esc(msg)
];
return [{ json: { slack_text: lines.join('\n') } }];

const fmt = $('Format Slack Notification').first().json;
const err = $input.first().json.error;
const msg = String(typeof err === 'string' ? err : ((err && (err.message || err.description)) || 'Unknown Slack error')).replace(/\s+/g, ' ').slice(0, 300);
const notes = [fmt.existingNotes, 'SLACK_NOTIFICATION_FAILED: ' + msg].filter(Boolean).join('\n');
return [{ json: { id: fmt.recordId, 'Processing Status': 'Needs Review', 'Processing Notes': notes } }];
